import sys, json
body = json.load(sys.stdin)["body"]
said = ""
for t in body.get("messages", []):
    if t.get("origin") == "user":
        said = t.get("text", "")
print(json.dumps({
    "header": {"finish_reason": "assistant"},
    "messages": [{"origin": "assistant", "type": "text", "text": "child-colony saw: " + said}]
}))
